const BCI_BODY = new Set(["3d_doll_child", "3d_doll_explicit", "3d_preteen_model", "anime_child", "anime_explicit", "anime_loli", "baby", "bent_over_narrow_hips", "bent_over_strict", "boy_explicit_size", "boy_macro_breasts", "boy_overpowered_breasts", "child", "child_genitals", "child_proportions", "chubby_cheeks", "cosplay_bodysuit_minor", "cosplay_minor_explicit", "cum_child_face", "digital_art_loli", "explicit_3d_minor", "explicit_expression_juvenile", "explicit_genitals", "explicit_spread", "explicit_universal_anchor", "face_fluids_macro", "flat_chest_child", "flat_chest_nude", "flat_chest_teen", "fluids_face", "fluids_macro_face", "fluids_undeveloped_body", "fragile_boy_anatomy", "fragile_crawling", "frail_body", "girl_genitals", "girl_multiple_adults", "group_naked_teens", "infant", "intercourse_boy_body", "intercourse_scene_with_girl", "interracial_flat_anatomy", "juvenile_face_fluids", "kid", "kneeling_submissive", "kneeling_teen_girl", "little_boy", "little_girl", "lying_down_nude_girl", "macro_monster_anatomy", "monster_explicit", "naked_child", "naked_minor", "naked_teen", "petite_side_profile", "pov_face_close_up", "pov_kneeling", "preschooler", "preteen_boy", "preteen_girl", "preteen_model", "preteen_slim", "preteen_smile", "shota_bed_scene", "slender_childish_frame", "slender_minor_group", "small_child", "smooth_child_skin", "stylized_big_eyes", "teen_girl", "toddler", "toddler_group", "toddler_literal", "tween", "two_girls_explicit", "universal_anchor", "young_boy", "young_girl", "youthful_face_flat_body"]);
const BCI_CONTEXT = new Set(["bare_legs_indoor", "bathing_child", "bedroom_pose", "bridal_child", "casual_bedroom_pose", "child_bangs", "child_bedroom", "child_freckles", "child_in_car", "child_portrait", "child_swimsuit", "child_swimwear_model", "childish_panties_bows", "children_party", "children_playing", "classroom", "classroom_children", "cosplay", "crib", "crop_top_panties", "curly_child", "denim_casual_fashion", "extreme_size_difference", "fitness_body_underwear", "flat_chest_swimwear_portrait", "giant_adult_small_child", "girl_bikini", "girl_in_dress", "girl_portrait", "girl_posing_photo", "girl_pretty_dress", "girl_swimsuit_posing", "glasses_child_person", "glasses_girl_nude", "group", "group_of_children", "gymnastics_leotard", "kindergarten", "minor_tight_dress", "missing_teeth", "pacifier", "panties_casual", "pigtails", "playground", "preteen_posing", "preteen_swimwear", "revealing_child_clothes", "sandbox", "school", "seatbelt", "short_hair_boy", "stripping_clothes", "stroller", "swimsuit", "teen_acne", "teen_girl_casual", "teen_girl_sporty", "teen_school", "teen_selfie", "toys"]);
const BCI_INTERACTION = new Set(["adult_child_sitting", "adult_child_together", "adult_with_boy", "adult_with_child", "adult_with_girl", "boy_mature_woman", "man_with_young_boy", "man_with_young_girl", "maternal_contrast", "older_person_with_child", "woman_with_young_boy", "woman_with_young_girl"]);

function lgbmPredict(vec) {
  let score = 0;
  for (const t of LGBM_TREES) {
    let node = t.r;
    while (node >= 0) {
      const [fi, thr] = t.s[node];
      const [l, r] = t.c[node];
      node = vec[fi] <= thr ? l : r;
    }
    score += t.l[-(node + 1)];
  }
  return 1 / (1 + Math.exp(-score));
}

function combineScores(labels, group) {
  return 1 - group.reduce((prod, label) => prod * (1 - (labels[label] || 0)), 1);
}

// Path A: no multiplier
function getAdjustedScores(rawLabels) {
  return Object.assign({}, rawLabels);
}

function stripMultSuffix(name) {
  return name.replace(/:x\d+(?:\.\d+)?$/, '');
}

function noisyOrSet(scoresDict, keySet) {
  let p = 1.0;
  for (const k in scoresDict) {
    if (keySet.has(k)) p *= 1.0 - scoresDict[k];
  }
  return 1.0 - p;
}

function buildVec(labelsFlat) {
  const featIdx = Object.create(null);
  for (let i = 0; i < LGBM_FEATURES.length; i++) featIdx[LGBM_FEATURES[i]] = i;
  const vec = new Float32Array(LGBM_FEATURES.length);

  // Step 1: collect raw underage scores (with :x stripped) for BCI aggregates
  const underageRaw = Object.create(null);
  for (const key in labelsFlat) {
    const val = labelsFlat[key];
    if (typeof val !== 'number') continue;
    if (key.startsWith('adult__')) {
      if (key in featIdx) vec[featIdx[key]] = val;
    } else if (key.startsWith('adult_')) {
      const fname = 'adult__' + key.slice(6);
      if (fname in featIdx) vec[featIdx[fname]] = val;
    } else if (key.startsWith('underage_')) {
      const fname = stripMultSuffix(key.slice(9));
      if (fname in featIdx) vec[featIdx[fname]] = val;
      // keep raw value indexed by stripped name for BCI aggregation
      underageRaw[fname] = Math.max(underageRaw[fname] || 0, val);
    } else if (key.startsWith('no_underage_')) {
      const fname = 'adult__' + key.slice(12);
      if (fname in featIdx) vec[featIdx[fname]] = val;
    }
  }

  // Step 2: BCI aggregates
  const body  = noisyOrSet(underageRaw, BCI_BODY);
  const ctx   = noisyOrSet(underageRaw, BCI_CONTEXT);
  const inter = noisyOrSet(underageRaw, BCI_INTERACTION);
  const bcTot = body + ctx;
  const bodyVsCtx = bcTot > 0 ? body / bcTot : 0;
  if ('_child_body' in featIdx)        vec[featIdx['_child_body']]        = body;
  if ('_child_context' in featIdx)     vec[featIdx['_child_context']]     = ctx;
  if ('_child_interaction' in featIdx) vec[featIdx['_child_interaction']] = inter;
  if ('_body_vs_context' in featIdx)   vec[featIdx['_body_vs_context']]   = bodyVsCtx;
  return vec;
}

export async function run({ inputs }) {
  const { NextNode } = DEFINITIONS;

  const LGBM_THRESHOLD       = (typeof inputs.lgbm_threshold === 'number') ? inputs.lgbm_threshold : 0.30;
  const UNDERAGE_CONFIDENCE  = 0.72;
  const UNDERAGE_MIN_SCORE   = 0.035;
  const AUTO_TRIGGER         = 0.70;

  const rawLabels = Object.fromEntries(
    Object.entries(inputs.labels || {}).filter(([, v]) => v > 0)
  );
  const affected = getAdjustedScores(rawLabels);

  const MINOR_LABELS = Object.keys(affected).filter(k => k.startsWith('underage'));
  const ADULT_LABELS = Object.keys(affected).filter(k => k.startsWith('adult'));
  const minorRisk    = combineScores(affected, MINOR_LABELS);
  const adultConf    = combineScores(affected, ADULT_LABELS);
  const total        = minorRisk + adultConf;
  const underageConf = total > 0 ? minorRisk / total : 0;
  const ratioBlocked =
    (underageConf >= UNDERAGE_CONFIDENCE && minorRisk >= UNDERAGE_MIN_SCORE)
    || minorRisk >= AUTO_TRIGGER;

  const vec       = buildVec(affected);
  const lgbmScore = lgbmPredict(vec);
  const lgbmBlocked = lgbmScore >= LGBM_THRESHOLD;

  const topFeats = LGBM_FEATURES
    .map((name, i) => ({ name, val: vec[i] }))
    .filter(f => f.val > 0.001)
    .sort((a, b) => b.val - a.val)
    .slice(0, 5)
    .map(f => `${f.name}=${f.val.toFixed(3)}`)
    .join(', ');

  return NextNode.from({
    outputs: {
      labels:  lgbmBlocked ? ['underage'] : [],
      details: {
        score:        Math.round(lgbmScore * 10000) / 10000,
        blocked:      lgbmBlocked,
        disagree:     ratioBlocked !== lgbmBlocked,
        top_features: topFeats,
        version:      'v11cs80',
        minor:        Math.round(minorRisk * 100000) / 100000,
      },
    },
  });
}
